import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with the given {@code name}.  
     * The method protects against directory‑traversal attacks by normalizing the
     * supplied path and ensuring that the resulting file resides within {@code dir}.
     *
     * @param dir  the base directory where the file should be created; must not be {@code null}
     * @param name the desired file name; may contain a query string which will be stripped
     * @return a {@link File} object that does not yet exist
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if the resolved path is outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory cannot be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name cannot be null");
        }

        // Strip query parameters if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        try {
            // Resolve the requested path against the base directory and normalize it
            Path basePath = dir.toPath().toAbsolutePath().normalize();
            Path resolvedPath = basePath.resolve(name).normalize();

            // Ensure the resolved path is still within the base directory
            if (!resolvedPath.startsWith(basePath)) {
                throw new IllegalArgumentException(
                        "Attempted directory traversal in file name: " + name);
            }

            File file = resolvedPath.toFile();

            // Determine prefix and suffix for generating a unique file name
            String fileName = file.getName();
            int dot = fileName.indexOf('.');
            String prefix = dot < 0 ? fileName : fileName.substring(0, dot);
            String suffix = dot < 0 ? "" : fileName.substring(dot);
            int index = 2;

            // Append numeric suffixes until a non‑existing file is found
            while (file.exists()) {
                String newName = prefix + "-" + index++ + suffix;
                file = basePath.resolve(newName).toFile();
            }

            // Create any missing parent directories
            file.getParentFile().mkdirs();

            return file;
        } catch (IOException e) {
            // Wrap checked exception into unchecked to keep method signature unchanged
            throw new RuntimeException("Failed to allocate file", e);
        }
    }

    // other methods

}
