import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

/**
 * A header delegate for {@link javax.ws.rs.core.MediaType} that performs
 * strict validation of the major and subtype components according to
 * RFC 7230.  The original implementation performed a limited blacklist
 * check which missed several dangerous characters such as CR/LF.  The
 * new implementation uses a whitelist based on the token definition
 * from the RFC and explicitly allows the single wildcard character
 * '*'.
 */
public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    /* Token characters as defined in RFC 7230 §3.2.6:
     *   tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" /
     *           "-" / "." / "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
     * The regular expression below matches one or more of these
     * characters.  It does not permit whitespace or control
     * characters, thereby preventing header injection via CR/LF.
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    /**
     * Validates a media‑type component (major or subtype).
     *
     * @param str the component to validate
     * @return {@code true} if {@code str} is a valid token or the single
     *         wildcard '*', otherwise {@code false}
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        // Allow the single wildcard character
        if ("*".equals(str)) {
            return true;
        }

        // Reject any control characters (including CR/LF)
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (Character.isISOControl(ch)) {
                return false;
            }
        }

        // Ensure the string matches the RFC token definition
        return TOKEN_PATTERN.matcher(str).matches();
    }

    // other methods
}
