        while (cb.remaining() > 0) {
            final CoderResult res = enc.encode(cb, out, false);

            if (res.isError()) {
                /* Handle malformed or unmappable input.  The original
                 * implementation failed to advance the source buffer
                 * position after dealing with these errors, which could
                 * lead to an infinite loop.  We now explicitly advance
                 * the position by the reported error length. */
