    env.put(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());

    LdapContext ctx = null;
    StartTlsResponse tls = null;
    try {
        // Create an unauthenticated context so we can negotiate TLS first
        ctx = new InitialLdapContext(env, null);

        // Negotiate STARTTLS
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        tls.negotiate();

        // Re‑bind with the supplied credentials over the secured channel
        Hashtable<String, Object> authEnv = new Hashtable<>(env);
        authEnv.put(Context.SECURITY_PRINCIPAL, principal);
        authEnv.put(Context.SECURITY_CREDENTIALS, credentials);
        ctx.reconnect(authEnv);   // performs the actual authentication

        // At this point the context is bound with the supplied credentials
        return ctx;
    } catch (IOException e) {
        // TLS negotiation failed – clean up and surface a communication error
        if (tls != null) {
            try { tls.close(); } catch (Exception ignored) {}
        }
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': ", server(jndiLdapContextFactory), e));
        throw new CommunicationException(e.getMessage(), e);
    } catch (NamingException ne) {
        // Authentication or other naming error – ensure resources are released
        if (tls != null) {
            try { tls.close(); } catch (Exception ignored) {}
        }
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Failed to authenticate with '%s': ", server(jndiLdapContextFactory), ne));
        throw ne;
    } catch (Throwable t) {
        // Unexpected failure – clean up and rethrow
        if (tls != null) {
            try { tls.close(); } catch (Exception ignored) {}
        }
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Unexpected failure to negotiate TLS connection with '%s': ", server(jndiLdapContextFactory), t));
