import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely extracts archive entries into {@code targetDirectory}.  The method
     * performs rigorous path validation to prevent path‑traversal attacks.
     *
     * @param supplier      provides the next readable archive entry
     * @param writer        writes the entry data to the output stream
     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if extraction fails or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the real path of the target directory once
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Basic sanity checks on the entry name
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has empty name");
            }
            // Reject absolute paths or paths that start with a separator
            if (entryName.startsWith("/") || entryName.startsWith("\\") ||
                entryName.contains(":")) {   // Windows drive letter
                throw new IOException("archive entry contains absolute path: " + entryName);
            }
            // Reject paths that contain '..' components
            if (entryName.contains("..")) {
                throw new IOException("archive entry contains path traversal component: " + entryName);
            }

            // Resolve and normalize the entry path relative to the target directory
            Path entryPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist
                if (!Files.isDirectory(entryPath)) {
                    Files.createDirectories(entryPath);
                }
            } else {
                // Ensure parent directories exist
                Path parent = entryPath.getParent();
                if (parent != null && !Files.isDirectory(parent)) {
                    Files.createDirectories(parent);
                }

                // Write the file contents
                try (OutputStream out = Files.newOutputStream(entryPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
```

