import org.apache.camel.Expression;
import org.apache.camel.NoTypeConversionAvailableException;
import org.apache.camel.Predicate;
import org.apache.camel.WrappedFile;
import org.apache.camel.component.bean.BeanInvocation;
import org.apache.camel.spi.NamespaceAware;
import org.apache.camel.support.ServiceSupport;

/**
 * A thread‑safe XPath builder that safely converts various input types to a {@link Document}.
 * <p>
 * The original implementation was vulnerable to XXE attacks because it relied on Camel's
 * default type converters which do not disable external entity resolution. This patched
 * version explicitly parses XML using a {@link DocumentBuilderFactory} configured with
 * secure features to prevent external entity expansion.
 */
public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<>();
    private volatile Class<?> documentType = Document.class;

    // other methods omitted for brevity

    /**
     * Converts the body to a suitable representation for XPath evaluation.
     *
     * @param exchange the current exchange
     * @param body     the message body
     * @return a {@link Document}, {@link InputSource}, or the original body
     * @throws Exception if conversion fails
     */
    @Override
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();
        Exception conversionFailure = null;

        // Attempt Camel's type conversion first
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                conversionFailure = e;
            }
        }

        // If conversion failed or returned null, handle common cases manually
        if (answer == null) {
            if (body instanceof WrappedFile) {
                InputStream is = exchange.getContext()
                                         .getTypeConverter()
                                         .convertTo(InputStream.class, exchange, body);
                // Wrap the stream in an InputSource for later parsing
                answer = new InputSource(is);
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext()
                                            .getTypeConverter()
                                            .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                // Parse the XML string securely
                if (Document.class.equals(type)) {
                    answer = parseSecurely(new InputSource(new StringReader((String) body)));
                } else {
                    answer = new InputSource(new StringReader((String) body));
                }
            } else if (body instanceof InputStream && Document.class.equals(type)) {
                // Securely parse an InputStream when a Document is requested
                answer = parseSecurely(new InputSource((InputStream) body));
            }
        }

        // If no specific document type was requested, return the original body
        if (type == null && answer == null) {
            return body;
        }

        // If we still have no answer, propagate the conversion error or throw a generic one
        if (answer == null) {
            if (conversionFailure != null) {
                throw conversionFailure;
            }
            throw new NoTypeConversionAvailableException(body, type);
        }

        return answer;
    }

    /**
     * Parses an {@link InputSource} into a {@link Document} using a factory configured
     * to mitigate XXE attacks.
     *
     * @param source the input source containing XML
     * @return a parsed {@link Document}
     * @throws ParserConfigurationException if the parser cannot be configured
     * @throws SAXException                 if a parsing error occurs
     * @throws IOException                  if an I/O error occurs
     */
    private static Document parseSecurely(InputSource source)
            throws ParserConfigurationException, SAXException, java.io.IOException {

        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // Disable DTDs entirely
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);

        DocumentBuilder builder = dbf.newDocumentBuilder();
        return builder.parse(source);
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods omitted for brevity
}
