import java.lang.reflect.GenericArrayType;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

import com.alibaba.fastjson.JSONArray;
import com.alibaba.fastjson.parser.DefaultJSONParser;
import com.alibaba.fastjson.parser.JSONLexer;
import com.alibaba.fastjson.parser.JSONToken;
import com.alibaba.fastjson.parser.deserializer.ObjectDeserializer;
import com.alibaba.fastjson.util.TypeUtils;

/**
 * A codec that safely deserialises JSON arrays into Java object arrays.
 *
 * <p>This implementation adds strict type validation to mitigate the
 * Fastjson deserialization vulnerability (CVE‑2017‑18318). Only a small
 * whitelist of primitive wrappers, common immutable types and dates are
 * permitted as component types. Any attempt to deserialize into an
 * unsupported type results in an {@link IllegalArgumentException}.</p>
 */
public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- */
    /* Whitelist of safe component types                                     */
    /* --------------------------------------------------------------------- */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES = new HashSet<>(
            Arrays.asList(
                    // Primitive wrappers
                    Boolean.class, Byte.class, Short.class, Integer.class, Long.class,
                    Float.class, Double.class, Character.class,
                    // Common immutable types
                    String.class, java.math.BigDecimal.class, java.math.BigInteger.class,
                    // Date/time types
                    java.util.Date.class,
                    java.time.LocalDate.class, java.time.LocalTime.class,
                    java.time.LocalDateTime.class, java.time.OffsetDateTime.class,
                    java.time.ZonedDateTime.class
            )
    );

    /**
     * Checks whether a component class is allowed for deserialization.
     *
     * @param cls the component class to check
     * @return true if the class is in the whitelist or a primitive type
     */
    private static boolean isAllowedComponentClass(Class<?> cls) {
        return cls != null && (cls.isPrimitive() || SAFE_COMPONENT_TYPES.contains(cls));
    }

    /* --------------------------------------------------------------------- */
    /* Deserialization logic                                                  */
    /* --------------------------------------------------------------------- */

    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        // Handle JSON null
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        // Handle JSON string literal → byte[]
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        Class<?> componentClass;
        Type componentType;

        // Resolve component type for generic array types
        if (type instanceof GenericArrayType) {
            GenericArrayType gArray = (GenericArrayType) type;
            componentType = gArray.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type objType = parser.getContext().type;

                if (objType instanceof ParameterizedType) {
                    ParameterizedType pType = (ParameterizedType) objType;
                    Type objRawType = pType.getRawType();
                    Type actualType = null;

                    if (objRawType instanceof Class) {
                        TypeVariable<?>[] params = ((Class<?>) objRawType).getTypeParameters();
                        for (int i = 0; i < params.length; ++i) {
                            if (params[i].getName().equals(typeVar.getName())) {
                                actualType = pType.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }

                    componentClass = actualType instanceof Class
                            ? (Class<?>) actualType
                            : Object.class;
                } else {
                    componentClass = TypeUtils.getClass(typeVar.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else {
            // Non-generic array type
            Class<?> clazz = (Class<?>) type;
            componentType = componentClass = clazz.getComponentType();
        }

        // Validate component type against whitelist
        if (!isAllowedComponentClass(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of array component type [" + componentClass + "] is not allowed");
        }

        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        return (T) toObjectArray(parser, componentClass, array);
    }

    /* --------------------------------------------------------------------- */
    /* Helper method to convert JSONArray to a typed array                  */
    /* --------------------------------------------------------------------- */
    @SuppressWarnings("unchecked")
    private <T> T toObjectArray(DefaultJSONParser parser, Class<?> componentType, JSONArray array) {
        // Fastjson already provides a safe conversion once the component type is validated
        return (T) array.toArray((Object[]) java.lang.reflect.Array.newInstance(componentType, array.size()));
    }

    // other methods omitted for brevity
}
```

